const safe = s => { const str = (s || "").toString(); return /^[+=\-@]/.test(str) ? "'" + str : str; };
const body = $input.first().json.body || $input.first().json;
const id = "CL" + Date.now();
const hoy = new Date().toISOString().slice(0, 10);
return [{
  json: {
    id_cliente: id,
    nombre: safe((body.nombre || "").toString().trim()),
    contacto: safe(body.contacto),
    tipo: body.tipo || "B2B",
    notas: safe(body.notas),
    activo: "si",
    fecha_alta: hoy
  }
}];

const items = $('Sheets read clientes').all();
const query = $('Webhook clientes-lista').item.json.query || {};
const filtro_activo = query.activo;
const busqueda = (query.busqueda || "").toString().toLowerCase();

let clientes = items.map(i => i.json).filter(c => c.id_cliente);

if (filtro_activo === "si" || filtro_activo === "no") {
  clientes = clientes.filter(c => c.activo === filtro_activo);
}
if (busqueda) {
  clientes = clientes.filter(c => (c.nombre || "").toLowerCase().includes(busqueda));
}
clientes.sort((a, b) => (a.nombre || "").localeCompare(b.nombre || ""));

return [{ json: { success: true, data: { clientes } } }];

const safe = s => { const str = (s || "").toString(); return /^[+=\-@]/.test(str) ? "'" + str : str; };
const body = $input.first().json.body || $input.first().json;
const id = "P" + Date.now();
const hoy = new Date().toISOString().slice(0, 10);
const cantidad = Number(body.cantidad || 0);
const precio = Number(body.precio_unitario || 0);
const total = Math.round(cantidad * precio * 100) / 100;
return [{
  json: {
    id_pedido: id,
    id_cliente: (body.id_cliente || "").toString(),
    genetica: safe(body.genetica),
    cantidad: cantidad,
    precio_unitario: precio,
    total: total,
    fecha_pedido: hoy,
    fecha_entrega_prometida: (body.fecha_entrega_prometida || "").toString(),
    fecha_entrega_real: "",
    estado: "pendiente",
    notas: safe(body.notas)
  }
}];

const items = $('Sheets read pedidos').all();
const query = $('Webhook pedidos-lista').item.json.query || {};
const filtro_estado = query.estado;
const filtro_cliente = query.id_cliente;

let pedidos = items.map(i => i.json).filter(p => p.id_pedido);

if (filtro_estado) pedidos = pedidos.filter(p => p.estado === filtro_estado);
if (filtro_cliente) pedidos = pedidos.filter(p => p.id_cliente === filtro_cliente);

pedidos.sort((a, b) => (a.fecha_entrega_prometida || "").localeCompare(b.fecha_entrega_prometida || ""));

return [{ json: { success: true, data: { pedidos } } }];

const movs_raw = $('Sheets read movimientos_bote').all().map(i => i.json).filter(m => m.id_mov);
const repartos_raw = $('Sheets read repartos').all().map(i => i.json).filter(r => r.id_reparto);
const cobros_raw = $('Sheets read cobros').all().map(i => i.json).filter(c => c.id_cobro);

let saldo = 0;
if (movs_raw.length > 0) {
  const last = movs_raw[movs_raw.length - 1];
  saldo = Number(last.saldo_despues || 0);
}

const ultimos_movimientos = movs_raw.slice(-20).reverse().map(m => ({
  id_mov: m.id_mov,
  fecha: m.fecha,
  tipo: m.tipo,
  importe: Number(m.importe || 0),
  concepto: m.concepto || "",
  socio: m.socio || "",
  saldo_despues: Number(m.saldo_despues || 0)
}));

const cobros = cobros_raw.slice(-40).reverse().map(c => ({
  id_cobro: c.id_cobro,
  id_pedido: c.id_pedido,
  fecha: c.fecha,
  importe: Number(c.importe || 0),
  metodo: c.metodo || "",
  quien_cobro: c.quien_cobro || "",
  bote: Number(c.bote_calculado || 0),
  reparto: Number(c.reparto_calculado || 0),
  por_socio: Number(c.por_socio_calculado || 0),
  modo_reparto: c.modo_reparto || "",
  nota_reparto: c.nota_reparto || ""
}));

const cobroIndex = {};
for (const c of cobros_raw) cobroIndex[c.id_cobro] = c;

const repartos_pendientes = { Eric: [], Noel: [] };
const bote_pendiente = [];

for (const p of repartos_raw) {
  if (p.estado !== "pendiente_entregar") continue;
  const cobro = cobroIndex[p.id_cobro];
  const entry = {
    id_reparto: p.id_reparto,
    id_cobro: p.id_cobro,
    fecha: p.fecha,
    importe: Number(p.importe || 0),
    quien_cobro: cobro ? (cobro.quien_cobro || "") : ""
  };
  if (p.socio === "Eric") repartos_pendientes.Eric.push(entry);
  else if (p.socio === "Noel") repartos_pendientes.Noel.push(entry);
  else if (p.socio === "bote") bote_pendiente.push(entry);
}

const entregados = repartos_raw.filter(r => r.estado === "entregado")
  .slice(-40).reverse().map(r => {
    const cobro = cobroIndex[r.id_cobro];
    return {
      id_reparto: r.id_reparto,
      id_cobro: r.id_cobro,
      socio: r.socio,
      importe: Number(r.importe || 0),
      fecha: r.fecha,
      fecha_entregado: r.fecha_entregado || "",
      quien_cobro: cobro ? (cobro.quien_cobro || "") : ""
    };
  });

return [{ json: { success: true, data: { saldo, ultimos_movimientos, cobros, repartos_pendientes, bote_pendiente, entregados } } }];

const safe = s => { const str = (s || "").toString(); return /^[+=\-@]/.test(str) ? "'" + str : str; };
const body = $input.first().json.body || $input.first().json;
const id_gasto = "G" + Date.now();
const id_mov = "M" + (Date.now() + 1);
const hoy = new Date().toISOString().slice(0, 10);
const importe = Number(body.importe || 0);
const concepto = safe(body.concepto);
const quien = body.quien_lo_gestiono || "Eric";
return [{
  json: {
    id_gasto, id_mov, fecha: hoy, concepto, importe, quien_lo_gestiono: quien
  }
}];

const prep = $('Prepare gastos row').item.json;
const movs = $('Sheets read movimientos_bote (for gastos)').all().map(i => i.json).filter(m => m.id_mov);
let saldo_previo = 0;
if (movs.length > 0) saldo_previo = Number(movs[movs.length - 1].saldo_despues || 0);
const saldo_despues = saldo_previo - prep.importe;

return [{
  json: {
    ...prep,
    saldo_despues,
    warning: saldo_despues < 0 ? "Saldo del bote en negativo" : null
  }
}];

const safe = s => { const str = (s || "").toString(); return /^[+=\-@]/.test(str) ? "'" + str : str; };
const body = $input.first().json.body || $input.first().json;
const id_mov = "M" + Date.now();
const hoy = new Date().toISOString().slice(0, 10);
const importe = Number(body.importe || 0);
const socio = body.socio || "Eric";
const concepto = safe(body.concepto || ("Aportación " + socio));
return [{
  json: { id_mov, fecha: hoy, tipo: "aportacion", importe, concepto, id_referencia: "", socio }
