const prep = $('Prepare aportacion row').item.json;
const movs = $('Sheets read movimientos_bote (for aportacion)').all().map(i => i.json).filter(m => m.id_mov);
let saldo_previo = 0;
if (movs.length > 0) saldo_previo = Number(movs[movs.length - 1].saldo_despues || 0);
return [{ json: { ...prep, saldo_despues: saldo_previo + prep.importe } }];

const safe = s => { const str = (s || "").toString(); return /^[+=\-@]/.test(str) ? "'" + str : str; };
const body = $input.first().json.body || $input.first().json;
const id_pedido = (body.id_pedido || "").toString();
const importe = Number(body.importe || 0);
const metodo = body.metodo || "efectivo";
const modo_reparto = body.modo_reparto || "regla_defecto";
const quien_cobro = body.quien_cobro || "Noel";

let bote, reparto, por_socio;
if (modo_reparto === "personalizado") {
  bote = Number(body.bote_personalizado || 0);
  reparto = Number(body.reparto_personalizado || 0);
  por_socio = reparto / 2;
  if (Math.abs(bote + reparto - importe) > 0.01) {
    throw new Error("bote + reparto != importe");
  }
} else {
  por_socio = Math.floor(importe * 2 / 5 / 20) * 20;
  reparto = por_socio * 2;
  bote = importe - reparto;
}

const nota_reparto = safe(body.nota_reparto);
const hoy = new Date().toISOString().slice(0, 10);
const ts = Date.now();

return [{
  json: {
    id_pedido, importe, metodo, modo_reparto, nota_reparto, quien_cobro,
    bote, reparto, por_socio,
    id_cobro: "C" + ts,
    id_reparto_E: "R" + ts + "-E",
    id_reparto_N: "R" + ts + "-N",
    id_reparto_B: "R" + ts + "-B",
    fecha: hoy
  }
}];

const prep = $('Prepare pedidos-entregar').item.json;
const pedidos = $('Sheets read pedidos (for entregar)').all().map(i => i.json).filter(p => p.id_pedido);
const pedido = pedidos.find(p => p.id_pedido === prep.id_pedido);
if (!pedido) throw new Error("pedido no encontrado: " + prep.id_pedido);
if (pedido.estado !== "pendiente") throw new Error("pedido ya " + pedido.estado);
return [{ json: prep }];

const prep = $('Prepare pedidos-entregar').item.json;
const hoy = prep.fecha;
const cobrador = prep.quien_cobro;

function mkRow(id, socio, importe) {
  const autoEntregado = socio === cobrador && importe > 0;
  let estado;
  if (importe === 0) estado = "no_aplica";
  else if (autoEntregado) estado = "entregado";
  else estado = "pendiente_entregar";
  return {
    id_reparto: id,
    id_cobro: prep.id_cobro,
    fecha: hoy,
    socio,
    importe,
    estado,
    fecha_entregado: autoEntregado ? hoy : ""
  };
}

return [
  { json: mkRow(prep.id_reparto_E, "Eric", prep.por_socio) },
  { json: mkRow(prep.id_reparto_N, "Noel", prep.por_socio) },
  { json: mkRow(prep.id_reparto_B, "bote", prep.bote) }
];

const body = $('Webhook repartos-marcar-entregado').item.json.body || {};
const id_reparto = (body.id_reparto || "").toString();
if (!id_reparto) throw new Error("id_reparto requerido");
const repartos = $('Sheets read repartos (for marcar)').all().map(i => i.json).filter(r => r.id_reparto);
const target = repartos.find(r => r.id_reparto === id_reparto);
if (!target) throw new Error("reparto no encontrado: " + id_reparto);
const hoy = new Date().toISOString().slice(0, 10);
return [{
  json: {
    id_reparto: target.id_reparto,
    socio: target.socio,
    importe: Number(target.importe || 0),
    estado_previo: target.estado,
    fecha_entregado: hoy,
    es_bote: target.socio === "bote",
    ya_entregado: target.estado === "entregado"
  }
}];

const target = $('Find reparto target').item.json;
if (!target.es_bote) return [];  // rama muerta si no es bote
if (target.ya_entregado) return [];  // idempotente
const movs = $('Sheets read mov_bote (for marcar)').all().map(i => i.json).filter(m => m.id_mov);
let saldo_previo = 0;
if (movs.length > 0) saldo_previo = Number(movs[movs.length - 1].saldo_despues || 0);
return [{
  json: {
    id_mov: "M" + Date.now(),
    fecha: new Date().toISOString().slice(0, 10),
    tipo: "cobro",
    importe: target.importe,
    concepto: "Ingreso al bote desde reparto " + target.id_reparto,
    id_referencia: target.id_reparto,
    socio: "",
    saldo_despues: saldo_previo + target.importe
  }
}];

const safe = s => { const str = (s || "").toString(); return /^[+=\-@]/.test(str) ? "'" + str : str; };
const body = $input.first().json.body || $input.first().json;
const importe = Number(body.importe || 0);
if (importe <= 0) throw new Error("importe inválido");
const concepto = safe(body.concepto || "Reparto del bote");
const parte_eric = Math.floor(importe / 2);
const parte_noel = importe - parte_eric;
const ts = Date.now();
const hoy = new Date().toISOString().slice(0, 10);
return [{
  json: {
    importe, concepto, parte_eric, parte_noel,
    id_mov: "M" + ts,
    id_cobro: "RB" + ts,
    id_reparto_E: "R" + ts + "-E",
    id_reparto_N: "R" + ts + "-N",
    fecha: hoy
  }
}];

const prep = $('Prepare bote-repartir').item.json;
const movs = $('Sheets read mov_bote (for repartir)').all().map(i => i.json).filter(m => m.id_mov);
let saldo_previo = 0;
if (movs.length > 0) saldo_previo = Number(movs[movs.length - 1].saldo_despues || 0);
if (prep.importe > saldo_previo) throw new Error("importe (" + prep.importe + ") > saldo del bote (" + saldo_previo + ")");
return [{ json: { ...prep, saldo_despues: saldo_previo - prep.importe } }];

const prep = $('Compute bote-repartir').item.json;
return [
  { json: { id_reparto: prep.id_reparto_E, id_cobro: prep.id_cobro, fecha: prep.fecha, socio: "Eric", importe: prep.parte_eric, estado: "pendiente_entregar", fecha_entregado: "" } },
  { json: { id_reparto: prep.id_reparto_N, id_cobro: prep.id_cobro, fecha: prep.fecha, socio: "Noel", importe: prep.parte_noel, estado: "pendiente_entregar", fecha_entregado: "" } }
];

const body = $('Webhook pedidos-crear').first().json.body || $('Webhook pedidos-crear').first().json;
const eventos = $('Read eventos_corte (for crear)').all().map(i => i.json);
const reservas = $('Read reservas_pedidos (for crear)').all().map(i => i.json);

function fail(msg) {
  return [{ json: { ok: false, error_msg: msg, body, _has_reservas: false, _reservas_to_insert: [] } }];
}

const cantidad = Number(body.cantidad || 0);
if (!body.id_cliente) return fail("id_cliente requerido");
if (!body.genetica) return fail("genetica requerida");
if (!cantidad || cantidad <= 0) return fail("cantidad invalida");
if (!body.precio_unitario || Number(body.precio_unitario) <= 0) return fail("precio invalido");

const reservasInput = Array.isArray(body.reservas) ? body.reservas : [];
const has_reservas = reservasInput.length > 0;

if (has_reservas) {
  const suma = reservasInput.reduce((a, r) => a + Number(r.cantidad || 0), 0);
  if (suma !== cantidad) return fail("suma de reservas (" + suma + ") no coincide con cantidad pedida (" + cantidad + ")");

  const reservasPorEvento = {};
  for (const r of reservas) {
    const e = String(r.id_evento || '').trim();
    if (!e) continue;
    const est = String(r.estado || '').trim().toLowerCase();
    if (est === 'reservada' || est === 'consumida') {
      reservasPorEvento[e] = (reservasPorEvento[e] || 0) + (Number(r.cantidad) || 0);
    }
  }

  const eventoPorId = {};
  for (const e of eventos) {
    const id = String(e.id_evento || '').trim();
    if (id) eventoPorId[id] = e;
  }

  for (const r of reservasInput) {
    const idEvento = String(r.id_evento || '').trim();
    const cant = Number(r.cantidad || 0);
    if (!idEvento) return fail("id_evento vacio en una reserva");
    if (cant <= 0) return fail("cantidad invalida en reserva de " + idEvento);
    const e = eventoPorId[idEvento];
    if (!e) return fail("lote no existe: " + idEvento);
    if ((String(e.estado || '').trim().toLowerCase() || 'activo') !== 'activo') {
      return fail("lote no activo: " + idEvento);
    }
    const total_neto = (Number(e.num_esquejes) || 0) - (Number(e.n_descartados) || 0);
    const reservado = reservasPorEvento[idEvento] || 0;
    const disponible = total_neto - reservado;
    if (cant > disponible) return fail("stock insuficiente en " + idEvento + ": pides " + cant + ", disponible " + disponible);
  }
}

const baseTs = Date.now();
const reservas_to_insert = reservasInput.map((r, i) => ({
  id_reserva: "RP" + baseTs + (i > 0 ? "-" + i : ""),
  id_evento: String(r.id_evento).trim(),
  cantidad: Number(r.cantidad),
}));

return [{
  json: {
    ok: true,
    error_msg: "",
    body,
    _has_reservas: has_reservas,
    _reservas_to_insert: reservas_to_insert,
  }
}];

const idPedido = $('Prepare pedidos row').first().json.id_pedido;
const reservasToInsert = $('Validar Reservas').first().json._reservas_to_insert || [];
const hoy = new Date().toISOString().slice(0, 10);

return reservasToInsert.map(r => ({
  json: {
    id_reserva: r.id_reserva,
    id_pedido: idPedido,
    id_evento: r.id_evento,
    cantidad: r.cantidad,
    estado: 'reservada',
    fecha_reserva: hoy,
    fecha_consumida: '',
    notas: '',
  }
}));

const idPedido = $('Prepare pedidos-entregar').first().json.id_pedido;
const filas = $input.all().map(i => i.json);

const reservas = filas
  .filter(r => String(r.id_pedido || '').trim() === idPedido)
  .filter(r => String(r.estado || '').trim().toLowerCase() === 'reservada')
  .map(r => ({
    id_reserva: String(r.id_reserva || '').trim(),
    id_evento: String(r.id_evento || '').trim(),
    cantidad: Number(r.cantidad) || 0,
  }));

return [{
  json: {
    id_pedido: idPedido,
    has_reservas: reservas.length > 0,
    reservas,
  }
}];

const reservas = $('Find Reservas Pedido').first().json.reservas || [];
const hoy = new Date().toISOString().slice(0, 10);

return reservas.map(r => ({
  json: {
    id_reserva: r.id_reserva,
    estado: 'consumida',
    fecha_consumida: hoy,
  }
}));

const body = $input.first().json.body || $input.first().json;
const id_pedido = String(body.id_pedido || '').trim();
if (!id_pedido) {
  return [{ json: { id_pedido: '', error_msg: 'id_pedido requerido', cancelable: false } }];
}
return [{ json: { id_pedido, error_msg: '', cancelable: null } }];

const prep = $('Prepare pedidos-cancelar').first().json;
if (prep.error_msg) return [{ json: prep }];

const idPedido = prep.id_pedido;
const filas = $input.all().map(i => i.json).filter(p => p.id_pedido);
const pedido = filas.find(p => String(p.id_pedido).trim() === idPedido);

if (!pedido) {
  return [{ json: { id_pedido: idPedido, error_msg: 'pedido no encontrado: ' + idPedido, cancelable: false } }];
}
const estado = String(pedido.estado || '').trim().toLowerCase();
if (estado !== 'pendiente') {
  return [{ json: { id_pedido: idPedido, error_msg: 'pedido no cancelable (estado actual: ' + estado + ')', cancelable: false } }];
}
return [{ json: { id_pedido: idPedido, error_msg: '', cancelable: true } }];

const idPedido = $('Prepare pedidos-cancelar').first().json.id_pedido;
const filas = $input.all().map(i => i.json);

const reservas = filas
  .filter(r => String(r.id_pedido || '').trim() === idPedido)
  .filter(r => String(r.estado || '').trim().toLowerCase() === 'reservada')
  .map(r => ({
    id_reserva: String(r.id_reserva || '').trim(),
    id_evento: String(r.id_evento || '').trim(),
    cantidad: Number(r.cantidad) || 0,
  }));

return [{
  json: {
    id_pedido: idPedido,
    has_reservas: reservas.length > 0,
    reservas,
  }
}];

const reservas = $('Find Reservas Cancelar').first().json.reservas || [];
const hoy = new Date().toISOString().slice(0, 10);

return reservas.map(r => ({
  json: {
    id_reserva: r.id_reserva,
    estado: 'liberada',
    fecha_consumida: hoy,
    notas: 'pedido cancelado',
  }
}));

const reservasConsumidas = ($('Find Reservas Pedido').first().json.reservas) || [];
const eventos = $('Read eventos_corte (for autocierre)').all().map(i => i.json);
const reservasTodas = $('Read reservas_pedidos (for autocierre)').all().map(i => i.json);

// IDs únicos de eventos afectados por este consumo
const idsAfectados = [...new Set(reservasConsumidas.map(r => String(r.id_evento || '').trim()).filter(Boolean))];

const hoy = new Date().toISOString().slice(0, 10);
const aCerrar = [];

for (const idEvento of idsAfectados) {
  const evento = eventos.find(e => String(e.id_evento || '').trim() === idEvento);
  if (!evento) continue;
  const estadoActual = (String(evento.estado || '').trim().toLowerCase()) || 'activo';
  if (estadoActual !== 'activo') continue;

  const total_neto = (Number(evento.num_esquejes) || 0) - (Number(evento.n_descartados) || 0);

  let consumidas = 0;
  let reservadas = 0;
  for (const r of reservasTodas) {
    if (String(r.id_evento || '').trim() !== idEvento) continue;
    const est = String(r.estado || '').trim().toLowerCase();
    const cant = Number(r.cantidad) || 0;
    if (est === 'consumida') consumidas += cant;
    else if (est === 'reservada') reservadas += cant;
  }

  // Cerrar solo si todo el lote se consumió y no quedan reservas pendientes
  if (consumidas >= total_neto && reservadas === 0 && total_neto > 0) {
    aCerrar.push({
      id_evento: idEvento,
      estado: 'cerrado',
      fecha_cierre: hoy,
      motivo_cierre: 'consumido',
    });
  }
}

return [{ json: { has_eventos_cerrar: aCerrar.length > 0, eventos: aCerrar } }];
